const SOURCES = ['Bioenergy', 'Coal', 'Gas', 'Hydro', 'Nuclear', 'Other fossil', 'Solar', 'Wind'];
const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const NL = String.fromCharCode(10);

const rows = $input.all().map((i) => i.json);
if (rows.length === 0) {
  throw new Error('ember_uk_monthly returned no rows');
}

const months = rows
  .map((r) => r.month)
  .filter((m) => typeof m === 'string' && /^[0-9]{4}-[0-9]{2}$/.test(m))
  .sort();
if (months.length === 0) {
  throw new Error('No valid YYYY-MM month values found in ember_uk_monthly');
}
const latest = months[months.length - 1];
const current = rows.filter((r) => r.month === latest);

const clean = current.find((r) => r.series === 'Clean');
if (!clean || typeof clean.share_pct !== 'number' || typeof clean.share_change_pts !== 'number') {
  throw new Error('Clean row missing or has null values for ' + latest);
}

const missing = SOURCES.filter((s) => !current.some((r) => r.series === s));
if (missing.length > 0) {
  throw new Error('Latest month ' + latest + ' is missing sources: ' + missing.join(', '));
}
const movers = current
  .filter((r) => SOURCES.includes(r.series))
  .map((r) => {
    if (typeof r.share_pct !== 'number' || typeof r.share_change_pts !== 'number') {
      throw new Error('Null value for ' + r.series + ' in ' + latest);
    }
    return { series: r.series, share_pct: r.share_pct, share_change_pts: r.share_change_pts };
  })
  .sort((a, b) => Math.abs(b.share_change_pts) - Math.abs(a.share_change_pts) || a.series.localeCompare(b.series))
  .slice(0, 3);

const year = latest.slice(0, 4);
const monthNum = parseInt(latest.slice(5, 7), 10);
const label = MONTH_NAMES[monthNum - 1] + ' ' + year;

const unsigned = (n) => String(n).replace(/^-/, '');
const allowed = [unsigned(clean.share_pct), unsigned(clean.share_change_pts), year, String(monthNum), latest.slice(5, 7)];
movers.forEach((m) => {
  allowed.push(unsigned(m.share_pct));
  allowed.push(unsigned(m.share_change_pts));
});

const lines = [
  'Month: ' + label,
  'Clean share of UK electricity generation: ' + clean.share_pct + '%',
  'Change in Clean share vs previous month: ' + clean.share_change_pts + ' percentage points',
  'Three biggest movers among individual generation sources, by absolute change in share:'
];
movers.forEach((m) => {
  lines.push('- ' + m.series + ': share ' + m.share_pct + '%, change ' + m.share_change_pts + ' percentage points');
});

return [{
  json: {
    month: latest,
    month_label: label,
    rows_read: rows.length,
    rows_in_month: current.length,
    clean_share_pct: clean.share_pct,
    clean_share_change_pts: clean.share_change_pts,
    movers: movers,
    allowed_numbers: allowed,
    facts_text: lines.join(NL)
  }
}];

const NL = String.fromCharCode(10);
const signals = $('Pick signals').first().json;
const ai = $input.first().json;

let text = ai.merged_response;
if (typeof text !== 'string' || text.trim() === '') {
  const parts = Array.isArray(ai.content) ? ai.content : [];
  text = parts.filter((p) => p && p.type === 'text').map((p) => (typeof p.text === 'string' ? p.text : '')).join('');
}
if (typeof text !== 'string' || text.trim() === '') {
  throw new Error('Briefing check failed: the AI step returned no text');
}

const lines = text.split(NL).map((l) => l.trim()).filter((l) => l.length > 0);
const problems = [];

if (lines.length > 5) {
  problems.push('briefing has ' + lines.length + ' lines, limit is 5');
}

const found = text.match(/[0-9]+(?:[.][0-9]+)?/g) || [];
const unexpected = found.filter((n) => !signals.allowed_numbers.includes(n));
if (unexpected.length > 0) {
  problems.push('numbers not in the supplied figures: ' + unexpected.join(', '));
}

if (!/^[^A-Za-z]*sales angle[ ]*:/i.test(lines[lines.length - 1])) {
  problems.push('last line does not start with "Sales angle:"');
}

if (problems.length > 0) {
  throw new Error('Briefing check failed: ' + problems.join('; ') + '. Text was: ' + text);
}

return [{ json: { text: lines.join(NL), line_count: lines.length, month: signals.month } }];
